<template><button class="inspiration-card" @click="$emit('open',item)"><view class="cover-wrap" :class="`type-${item.contentType}`"><AppImage :src="item.thumbnailUrl||item.coverUrl" :fallback="item.coverUrl" :alt="item.title" width="100%" height="100%" radius="7px"/><text class="ai-mark">AI生成示例</text><text class="type-mark">{{ typeLabel }}</text><view v-if="item.contentType==='video'" class="play-mark">▶</view></view><text class="card-title">{{ item.title }}</text><text class="prompt-summary">{{ item.description }}</text><view class="card-foot"><text>♡ {{ item.favoriteCount }} · 使用 {{ item.useCount }}</text><text class="use-action">生成同款</text></view></button></template>
<script setup lang="ts">import{computed}from"vue";import AppImage from"../AppImage.vue";import type{InspirationTemplate}from"../../features/inspiration/types";const props=defineProps<{item:InspirationTemplate}>();defineEmits<{open:[item:InspirationTemplate]}>();const typeLabel=computed(()=>({image:"图片",video:"视频",ppt:"PPT"}[props.item.contentType]));</script>
<style scoped>.inspiration-card{width:100%;margin:0;padding:8px;border:1px solid #e8eaf1;border-radius:8px;background:#fff;text-align:left;box-shadow:0 6px 20px rgba(31,39,67,.05)}.inspiration-card::after{display:none}.cover-wrap{position:relative;height:190px;overflow:hidden;border-radius:7px}.cover-wrap.type-video{height:150px}.cover-wrap.type-ppt{height:170px}.ai-mark,.type-mark{position:absolute;z-index:3;top:8px;padding:4px 7px;border-radius:4px;color:#fff;background:rgba(19,25,47,.72);font-size:8px}.ai-mark{left:8px}.type-mark{right:8px}.play-mark{position:absolute;z-index:3;top:50%;left:50%;display:grid;width:38px;height:38px;place-items:center;transform:translate(-50%,-50%);border-radius:50%;color:#fff;background:rgba(28,34,58,.68);font-size:14px}.card-title,.prompt-summary{display:block}.card-title{margin:10px 3px 0;color:#171c2d;font-size:14px;font-weight:700;line-height:20px}.prompt-summary{height:34px;margin:4px 3px 0;overflow:hidden;color:#7c8497;font-size:10px;line-height:17px}.card-foot{display:flex;margin:10px 3px 2px;align-items:center;justify-content:space-between;color:#8a92a5;font-size:9px}.use-action{color:#4a6cff;font-weight:650}</style>
